/*
 * A266912  Numbers n which are anagrams of n+18.
 * https://oeis.org/A266912
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn, base, easy
 * Formula:   a(n) is the n-th positive integer that is an anagram of n+18.
 *            The sequence is generated by brute‑force search with memoisation
 * Range:     u8 n <= 19, u16 n <= 53, u32 n <= 53, u64 n <= 53, u128 n <= 53,
 *            big any n
 * Helpers:   digit_counts
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

/* The definition below must match the build environment:  seq_t and idx_t
   are provided by the compiler harness.  */
#include <stdlib.h>
#include <stdbool.h>
#include "../utils/digit_counts.h"

/* Helper that tests whether a number x is an anagram of x+18.  */
static bool is_anagram(seq_t x)
{
    unsigned char cnt1[10] = {0};
    unsigned char cnt2[10] = {0};

    digit_counts(x, cnt1);
    digit_counts(x + (seq_t)18, cnt2);

    for (int i = 0; i < 10; ++i) {
        if (cnt1[i] != cnt2[i])
            return false;
    }
    return true;
}

/* Global state for memoisation.  All static data are initialised lazily.  */
static seq_t *seq = NULL;          /* array of found terms          */
static size_t seq_cap = 0;         /* current capacity              */
static size_t seq_size = 0;        /* how many terms are stored    */
static seq_t next_candidate = 1;   /* candidate number that hasn't
                                     *  been examined yet             */

/* External function required by the harness.  */
seq_t a(idx_t n)
{
    /* Index n is 1‑based in OEIS notation.  */
    if (n == 0) {
        /* Handling of n==0 is undefined by the spec; we return 0.  */
        return (seq_t)0;
    }

    /* Ensure the table has at least n entries.  */
    while (seq_size < (size_t)n) {
        /* Grow the array when necessary.  */
        if (seq_size == seq_cap) {
            size_t new_cap = (seq_cap == 0) ? 32 : seq_cap * 2;
            seq_t *tmp = (seq_t *)realloc(seq, new_cap * sizeof(seq_t));
            if (!tmp) {
                /* Allocation failed; return 0 (the build harness may
                   treat this as an error).  */
                return (seq_t)0;
            }
            seq = tmp;
            seq_cap = new_cap;
        }

        /* Search for the next term starting from the last candidate.  */
        for (; ; ++next_candidate) {
            if (is_anagram(next_candidate)) {
                seq[seq_size++] = next_candidate;
                /* Advance the candidate for the next search. */
                next_candidate = next_candidate + (seq_t)1;
                break;
            }
        }
    }

    /* Return the required term (indexing is 0‑based in C).  */
    return seq[n - 1];
}
